package com.modernbooks;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.FontID;

@Getter
@RequiredArgsConstructor
public enum GameFont
{
	DEFAULT("Game default", -1),
	PLAIN("Plain", FontID.PLAIN_12),
	BOLD("Bold", FontID.BOLD_12),
	QUILL("Quill", FontID.QUILL_MEDIUM),
	VERDANA("Verdana", FontID.VERDANA_13),
	VERDANA_BOLD("Verdana bold", FontID.VERDANA_13_BOLD),
	TAHOMA("Tahoma", FontID.TAHOMA_11),
	FAIRY("Fairy", FontID.FAIRY_SMALL),
	BARBARIAN("Barbarian", FontID.BARBARIAN),
	SUROK("Surok", FontID.SUROK);

	private final String displayName;
	/**
	 * The font id, or -1 to leave the game's font alone
	 */
	private final int fontId;

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.modernbooks;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the modern book and its page-turn buttons underneath the book interface,
 * in place of the game's page models and stone arrows
 */
class ModernBookOverlay extends Overlay
{
	private final Client client;
	private final ModernBooksPlugin plugin;
	private final ModernBookPainter painter = new ModernBookPainter();

	@Inject
	ModernBookOverlay(Client client, ModernBooksPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.UNDER_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Rectangle book = plugin.getModernBookArea();
		if (book == null)
		{
			return null;
		}

		BufferedImage image = painter.get(book.width, book.height);
		graphics.drawImage(image, book.x - ModernBookPainter.MARGIN, book.y - ModernBookPainter.MARGIN, null);

		Point mouse = client.getMouseCanvasPosition();
		for (ModernBooksPlugin.ArrowButton arrow : plugin.getArrowButtons())
		{
			boolean hover = arrow.getBounds().contains(mouse.getX(), mouse.getY());
			ModernBookPainter.paintArrow(graphics, arrow.getBounds(), arrow.isRight(), hover);
		}
		return null;
	}
}

package com.modernbooks;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Path2D;
import java.awt.geom.Rectangle2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.Random;

/**
 * Draws the modern book: a leather cover around two clean parchment pages, shaped with shading rather than outlines.
 * The book is cached, since it only changes when its size does.
 */
class ModernBookPainter
{
	/**
	 * Extra space around the book in the image, for the drop shadow
	 */
	static final int MARGIN = 8;

	private static final Color COVER_TOP = new Color(0x5A3720);
	private static final Color COVER_BOTTOM = new Color(0x3A2213);
	private static final Color PAGE_LIGHT = new Color(0xF3E6C6);
	private static final Color PAGE_DARK = new Color(0xE4CFA2);
	private static final Color PAGE_SHADE = new Color(0x9C7C48);
	private static final Color PAGE_UNDER = new Color(0xCDB27C);

	private BufferedImage cached;
	private int cachedWidth;
	private int cachedHeight;

	/**
	 * @return the book image for a book of this size, with {@link #MARGIN} pixels of shadow on each side
	 */
	BufferedImage get(int width, int height)
	{
		if (cached == null || cachedWidth != width || cachedHeight != height)
		{
			cached = paint(width, height);
			cachedWidth = width;
			cachedHeight = height;
		}
		return cached;
	}

	private static BufferedImage paint(int width, int height)
	{
		BufferedImage img = new BufferedImage(width + MARGIN * 2, height + MARGIN * 2, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.translate(MARGIN, MARGIN);

		// Soft drop shadow
		for (int i = MARGIN; i > 0; i--)
		{
			g.setColor(new Color(0, 0, 0, 10));
			g.fill(new RoundRectangle2D.Float(-i + 1, -i + 3, width + 2 * i - 2, height + 2 * i - 2, 8 + i, 8 + i));
		}

		// Leather cover, with a faint highlight along the top edge
		RoundRectangle2D cover = new RoundRectangle2D.Float(0, 0, width, height, 10, 10);
		g.setPaint(new GradientPaint(0, 0, COVER_TOP, 0, height, COVER_BOTTOM));
		g.fill(cover);
		grain(g, cover, new Random(7), width * height / 40, new Color(255, 255, 255, 7), new Color(0, 0, 0, 16));
		g.setPaint(new GradientPaint(0, 0, new Color(255, 255, 255, 28), 0, 4, new Color(255, 255, 255, 0)));
		g.fill(new RoundRectangle2D.Float(1, 1, width - 2, 6, 8, 8));

		// Pages
		int inset = Math.max(6, Math.round(width * 0.02f));
		int gutter = Math.max(3, Math.round(width * 0.008f));
		float pageW = (width - 2 * inset - gutter) / 2f;
		float pageH = height - 2 * inset;
		float leftX = inset;
		float rightX = inset + pageW + gutter;

		// A darker layer peeking out under each page's outer edge gives the pages some thickness
		int thick = Math.max(2, Math.round(width * 0.005f));
		g.setColor(PAGE_UNDER);
		g.fill(new RoundRectangle2D.Float(leftX - thick, inset + 1, pageW, pageH, 6, 6));
		g.fill(new RoundRectangle2D.Float(rightX + thick, inset + 1, pageW, pageH, 6, 6));

		page(g, leftX, inset, pageW, pageH, true);
		page(g, rightX, inset, pageW, pageH, false);

		g.dispose();
		return img;
	}

	private static void page(Graphics2D g, float x, float y, float w, float h, boolean left)
	{
		// Rounded on the outer corners only; the spine side stays square
		Path2D shape = pageShape(x, y, w, h, 5, left);
		g.setPaint(new GradientPaint(0, y, PAGE_LIGHT, 0, y + h, PAGE_DARK));
		g.fill(shape);

		Shape clip = g.getClip();
		g.clip(shape);
		Rectangle2D b = shape.getBounds2D();
		grain(g, shape, new Random(left ? 11 : 13), (int) (w * h / 30), new Color(255, 255, 255, 16), new Color(120, 90, 40, 10));

		// The page curving down into the spine
		float spine = left ? x + w : x;
		float curve = w * 0.12f;
		g.setPaint(new GradientPaint(spine, 0, withAlpha(PAGE_SHADE, 95), left ? spine - curve : spine + curve, 0, withAlpha(PAGE_SHADE, 0)));
		g.fill(b);
		// Slightly darker toward the outer edge, top and bottom
		float outer = left ? x : x + w;
		float edge = w * 0.08f;
		g.setPaint(new GradientPaint(outer, 0, withAlpha(PAGE_SHADE, 45), left ? outer + edge : outer - edge, 0, withAlpha(PAGE_SHADE, 0)));
		g.fill(b);
		g.setPaint(new GradientPaint(0, y, withAlpha(PAGE_SHADE, 30), 0, y + h * 0.06f, withAlpha(PAGE_SHADE, 0)));
		g.fill(b);
		g.setPaint(new GradientPaint(0, y + h, withAlpha(PAGE_SHADE, 40), 0, y + h * 0.92f, withAlpha(PAGE_SHADE, 0)));
		g.fill(b);
		g.setClip(clip);
	}

	private static Path2D pageShape(float x, float y, float w, float h, float r, boolean left)
	{
		Path2D p = new Path2D.Float();
		if (left)
		{
			p.moveTo(x + w, y);
			p.lineTo(x + r, y);
			p.quadTo(x, y, x, y + r);
			p.lineTo(x, y + h - r);
			p.quadTo(x, y + h, x + r, y + h);
			p.lineTo(x + w, y + h);
		}
		else
		{
			p.moveTo(x, y);
			p.lineTo(x + w - r, y);
			p.quadTo(x + w, y, x + w, y + r);
			p.lineTo(x + w, y + h - r);
			p.quadTo(x + w, y + h, x + w - r, y + h);
			p.lineTo(x, y + h);
		}
		p.closePath();
		return p;
	}

	/**
	 * Draws a page-turn button: a small leather button with a cream chevron, lighter while hovered
	 */
	static void paintArrow(Graphics2D g, Rectangle bounds, boolean right, boolean hover)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// A little smaller than the click area, centred in it
		float h = Math.min(bounds.height * 0.75f, bounds.width * 0.55f);
		float w = h * 1.5f;
		float x = (float) bounds.getCenterX() - w / 2;
		float y = (float) bounds.getCenterY() - h / 2;
		RoundRectangle2D button = new RoundRectangle2D.Float(x, y, w, h, h * 0.5f, h * 0.5f);

		g2.setColor(new Color(0, 0, 0, 50));
		g2.fill(new RoundRectangle2D.Float(x, y + 1.5f, w, h, h * 0.5f, h * 0.5f));
		Color top = hover ? new Color(0x7A4E2E) : COVER_TOP;
		Color bottom = hover ? COVER_TOP : COVER_BOTTOM;
		g2.setPaint(new GradientPaint(0, y, top, 0, y + h, bottom));
		g2.fill(button);

		float cx = x + w / 2;
		float cy = y + h / 2;
		float size = h * 0.2f;
		float dir = right ? 1 : -1;
		Path2D chevron = new Path2D.Float();
		chevron.moveTo(cx - dir * size * 0.6f, cy - size);
		chevron.lineTo(cx + dir * size * 0.6f, cy);
		chevron.lineTo(cx - dir * size * 0.6f, cy + size);
		g2.setStroke(new BasicStroke(Math.max(1.5f, h * 0.11f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g2.setColor(PAGE_LIGHT);
		g2.draw(chevron);
		g2.dispose();
	}

	private static void grain(Graphics2D g, Shape shape, Random rnd, int count, Color light, Color dark)
	{
		Rectangle2D b = shape.getBounds2D();
		Shape clip = g.getClip();
		g.clip(shape);
		for (int i = 0; i < count; i++)
		{
			int x = (int) (b.getX() + rnd.nextDouble() * b.getWidth());
			int y = (int) (b.getY() + rnd.nextDouble() * b.getHeight());
			g.setColor(rnd.nextBoolean() ? light : dark);
			g.fillRect(x, y, 1, 1);
		}
		g.setClip(clip);
	}

	private static Color withAlpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}
}

package com.modernbooks;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(ModernBooksConfig.GROUP)
public interface ModernBooksConfig extends Config
{
	String GROUP = "modernbooks";

	@ConfigItem(
		keyName = "modernStyle",
		name = "Modern book style",
		description = "Replace the old parchment book pages with a cleaner leather and parchment design",
		position = 1
	)
	default boolean modernStyle()
	{
		return true;
	}

	@ConfigItem(
		keyName = "font",
		name = "Font",
		description = "Font used in books, letters and message scrolls",
		position = 2
	)
	default GameFont font()
	{
		return GameFont.DEFAULT;
	}
}

package com.modernbooks;

import com.google.inject.Provides;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.WeakHashMap;
import javax.inject.Inject;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Modern Books",
	description = "A cleaner, modern look and a font of your choice for books, letters and scrolls",
	tags = {"book", "books", "font", "journal", "scroll", "letter", "modern"}
)
public class ModernBooksPlugin extends Plugin
{
	// Interfaces whose text gets the chosen font
	private static final int[] FONT_GROUPS = {
		InterfaceID.BOOK, InterfaceID.INDEXED_BOOK,
		InterfaceID.MESSAGESCROLL, InterfaceID.MESSAGESCROLL2,
		InterfaceID.MESSAGESCROLL_HANDWRITING, InterfaceID.MESSAGESCROLL_HANDWRITING_2,
		InterfaceID.MESSAGESCROLL_HANDWRITING_3, InterfaceID.LETTERSCROLL, InterfaceID.LONGSCROLL
	};

	// Book titles keep the game's font, since they sit outside the pages
	private static final Set<Integer> KEEP_FONT = Set.of(InterfaceID.Book.TITLE, InterfaceID.IndexedBook.TITLE);

	// The 3D parchment and stone arrows that the modern style replaces
	private static final int[] REPLACED_WIDGETS = {
		InterfaceID.Book.BACKGROUND_MODEL, InterfaceID.Book.PAGE_LEFT_MODEL, InterfaceID.Book.PAGE_RIGHT_MODEL,
		InterfaceID.Book.PAGE_LEFT_GRAPHIC, InterfaceID.Book.PAGE_RIGHT_GRAPHIC,
		InterfaceID.IndexedBook.BACKGROUND_MODEL, InterfaceID.IndexedBook.PAGE_LEFT_MODEL, InterfaceID.IndexedBook.PAGE_RIGHT_MODEL,
		InterfaceID.IndexedBook.PAGE_LEFT_GRAPHIC, InterfaceID.IndexedBook.PAGE_RIGHT_GRAPHIC
	};

	// Space between the outermost page content and the edge of the drawn book.
	// More at the top, so the text doesn't sit right against the top of the page
	private static final int BOOK_PADDING = 14;
	private static final int BOOK_PADDING_TOP = 28;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ModernBooksConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ModernBookOverlay overlay;

	// Config values cached here, since reading config goes through a proxy and string lookups
	private boolean modernStyle;
	private int fontId = -1;

	// Set when book widgets may have been (re)built and need updating
	private boolean widgetsDirty;
	private boolean logBookBounds;

	// Original fonts of widgets we've changed, so they can be put back. Weak keys so closed interfaces are dropped
	private final Map<Widget, Integer> originalFonts = new WeakHashMap<>();
	private final Set<Widget> hiddenWidgets = Collections.newSetFromMap(new WeakHashMap<>());

	@Override
	protected void startUp()
	{
		loadConfig();
		widgetsDirty = true;
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		clientThread.invoke(() ->
		{
			restoreFonts();
			restoreReplaced();
		});
	}

	@Provides
	ModernBooksConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ModernBooksConfig.class);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ModernBooksConfig.GROUP.equals(event.getGroup()))
		{
			loadConfig();
			widgetsDirty = true;
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		// Book pages are filled in by scripts, eg. when turning the page
		widgetsDirty = true;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		widgetsDirty = true;
		if (event.getGroupId() == InterfaceID.BOOK || event.getGroupId() == InterfaceID.INDEXED_BOOK)
		{
			logBookBounds = true;
		}
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		if (logBookBounds)
		{
			logBookBounds = false;
			log.debug("Book area {}", getModernBookArea());
		}

		if (!widgetsDirty)
		{
			return;
		}
		widgetsDirty = false;

		applyFonts();
		if (modernStyle)
		{
			hideReplaced();
		}
		else
		{
			restoreReplaced();
		}
	}

	/**
	 * Where to draw the modern book, or null if it shouldn't be drawn
	 */
	Rectangle getModernBookArea()
	{
		if (!modernStyle)
		{
			return null;
		}

		Rectangle area = bookArea(InterfaceID.Book.PAGE_LEFT_TEXT, InterfaceID.Book.PAGE_RIGHT_TEXT,
			InterfaceID.Book.PAGE_LEFT_NUMBER, InterfaceID.Book.PAGE_RIGHT_NUMBER,
			InterfaceID.Book.PAGE_LEFT_BUTTON, InterfaceID.Book.PAGE_RIGHT_BUTTON);
		if (area == null)
		{
			area = bookArea(InterfaceID.IndexedBook.PAGE_LEFT_TEXT, InterfaceID.IndexedBook.PAGE_RIGHT_TEXT,
				InterfaceID.IndexedBook.PAGE_LEFT_NUMBER, InterfaceID.IndexedBook.PAGE_RIGHT_NUMBER,
				InterfaceID.IndexedBook.PAGE_LEFT_BUTTON, InterfaceID.IndexedBook.PAGE_RIGHT_BUTTON);
		}
		return area;
	}

	/**
	 * The smallest box around both pages' text, page numbers and page buttons, plus some padding
	 */
	private Rectangle bookArea(int leftText, int rightText, int... extras)
	{
		Widget left = client.getWidget(leftText);
		Widget right = client.getWidget(rightText);
		if (left == null || right == null || left.isHidden())
		{
			return null;
		}

		Rectangle area = left.getBounds().union(right.getBounds());
		for (int id : extras)
		{
			Widget w = client.getWidget(id);
			if (w != null && !w.isSelfHidden())
			{
				area = area.union(w.getBounds());
			}
		}
		area.grow(BOOK_PADDING, BOOK_PADDING);
		area.y -= BOOK_PADDING_TOP - BOOK_PADDING;
		area.height += BOOK_PADDING_TOP - BOOK_PADDING;
		return area;
	}

	/**
	 * The page-turn buttons to draw, as their bounds and whether each points right
	 */
	List<ArrowButton> getArrowButtons()
	{
		List<ArrowButton> arrows = new ArrayList<>(2);
		if (!modernStyle)
		{
			return arrows;
		}
		addArrow(arrows, InterfaceID.Book.PAGE_LEFT_BUTTON, InterfaceID.Book.PAGE_LEFT_GRAPHIC, false);
		addArrow(arrows, InterfaceID.Book.PAGE_RIGHT_BUTTON, InterfaceID.Book.PAGE_RIGHT_GRAPHIC, true);
		addArrow(arrows, InterfaceID.IndexedBook.PAGE_LEFT_BUTTON, InterfaceID.IndexedBook.PAGE_LEFT_GRAPHIC, false);
		addArrow(arrows, InterfaceID.IndexedBook.PAGE_RIGHT_BUTTON, InterfaceID.IndexedBook.PAGE_RIGHT_GRAPHIC, true);
		return arrows;
	}

	private void addArrow(List<ArrowButton> arrows, int buttonId, int graphicId, boolean right)
	{
		Widget button = client.getWidget(buttonId);
		Widget graphic = client.getWidget(graphicId);
		// Only where the game would show its arrow, ie. we hid the graphic, not the game
		if (button != null && !button.isHidden() && graphic != null && hiddenWidgets.contains(graphic))
		{
			arrows.add(new ArrowButton(button.getBounds(), right));
		}
	}

	@Value
	static class ArrowButton
	{
		Rectangle bounds;
		boolean right;
	}

	private void loadConfig()
	{
		modernStyle = config.modernStyle();
		fontId = config.font().getFontId();
	}

	private void applyFonts()
	{
		if (fontId == -1)
		{
			restoreFonts();
			return;
		}

		for (int group : FONT_GROUPS)
		{
			for (int child = 0; ; child++)
			{
				Widget w = client.getWidget(group, child);
				if (w == null)
				{
					break;
				}
				applyFont(w);
			}
		}
	}

	private void applyFont(Widget w)
	{
		if (w.getType() == WidgetType.TEXT && !KEEP_FONT.contains(w.getId()))
		{
			originalFonts.putIfAbsent(w, w.getFontId());
			if (w.getFontId() != fontId)
			{
				w.setFontId(fontId);
			}
		}

		Widget[] dynamic = w.getDynamicChildren();
		if (dynamic != null)
		{
			for (Widget c : dynamic)
			{
				if (c != null)
				{
					applyFont(c);
				}
			}
		}
	}

	private void restoreFonts()
	{
		originalFonts.forEach(Widget::setFontId);
		originalFonts.clear();
	}

	private void hideReplaced()
	{
		for (int id : REPLACED_WIDGETS)
		{
			Widget w = client.getWidget(id);
			if (w != null && !w.isSelfHidden())
			{
				w.setHidden(true);
				hiddenWidgets.add(w);
			}
		}
	}

	private void restoreReplaced()
	{
		hiddenWidgets.forEach(w -> w.setHidden(false));
		hiddenWidgets.clear();
	}
}

